// swift-tools-version: 5.9
// Lucide and Lucide Lab icons for Swift, generated by `bun run generate` from the same pinned
// Lucide releases and outlines as the pen.dev libraries in dist/. Sources/ is generated; edit
// tools/generate.ts and tools/swift.ts instead.
import PackageDescription

let package = Package(
    name: "LucideFoundry",
    platforms: [.macOS(.v13), .iOS(.v16)],
    products: [
        // Separate modules, because Lucide Lab can use an id Lucide uses for a different icon.
        .library(name: "Lucide", targets: ["Lucide"]),
        .library(name: "LucideLab", targets: ["LucideLab"]),
    ],
    targets: [
        .target(name: "Lucide", resources: [.process("Lucide.xcassets")]),
        .target(name: "LucideLab", resources: [.process("LucideLab.xcassets")]),
        .testTarget(name: "LucideTests", dependencies: ["Lucide", "LucideLab"]),
    ]
)
